window.ELSEWHERE_GALLERY_TEMPLATE = "<style>\n:host{all:initial;color-scheme:dark}*,*::before,*::after{box-sizing:border-box}button{font:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.backdrop{position:fixed;inset:0;z-index:2147483647;display:grid;place-items:center;overflow:hidden;background:#08090b;font-family:Manrope,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color:#f5f5f7;animation:reveal 420ms ease-out}\n.backdrop:focus{outline:none}\n\n.pin-board{position:absolute;inset:-90px -35px;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:20px;pointer-events:none;filter:blur(7px);overflow:hidden;transform:scale(1.05)}\n.pin-column{display:flex;flex-direction:column;gap:20px;transform:translateY(calc(var(--column) * -34px));min-width:0}\n.pin-column img{display:block;width:100%;object-fit:cover;border-radius:17px;background:#252830}\n.board-shade{position:absolute;inset:0;background:radial-gradient(ellipse at center,#08090bcc,#08090be0 75%);pointer-events:none}\n@media(max-width:700px){.pin-board{width:850px;left:50%;right:auto;transform:translateX(-50%) scale(1.05);gap:14px}.pin-column{gap:14px}.pin-column img{border-radius:12px}}\n\n.pin-board{z-index:0;animation:board-reveal 900ms cubic-bezier(.2,.8,.2,1)}.board-shade{z-index:1}\n.pin-column{animation:column-arrive 1100ms cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--column) * 45ms)}\n@keyframes board-reveal{from{opacity:0}to{opacity:1}}\n@keyframes column-arrive{from{translate:0 50px}to{translate:0 0}}\n@keyframes reveal{from{opacity:0}to{opacity:1}}\n@keyframes arrive{from{opacity:.5;transform:translateX(var(--entry,0px)) scale(.985)}to{opacity:1;transform:none}}\n.stage{position:relative;z-index:2;display:grid;width:100%;height:100%;place-items:center;padding:80px 80px 78px;min-height:0}\n.image{display:block;max-width:min(calc(100vw - 160px),1500px);max-height:calc(100dvh - 158px);border-radius:12px;box-shadow:0 24px 100px #000a;object-fit:contain;cursor:zoom-in;user-select:none;-webkit-user-drag:none;transition:opacity 160ms ease}\n.image:not([src]){visibility:hidden}.image.switching{opacity:.45;cursor:wait}.image.arriving{animation:arrive 320ms cubic-bezier(.2,.8,.2,1)}\n.topbar{position:absolute;z-index:3;inset:20px 24px auto;display:flex;align-items:center;justify-content:flex-start;height:38px;pointer-events:none}\n.brand{font:26px/1 Instrument,Georgia,serif;letter-spacing:-1px;color:#eeeff3}.top-actions{position:absolute;right:0;top:0;pointer-events:auto}\n.close,.nav{display:inline-flex;align-items:center;justify-content:center;border:1px solid #ffffff20;background:#ffffff0b;color:#f5f5f7;transition:background 180ms,transform 180ms,border-color 180ms;backdrop-filter:blur(12px)}\n.close{width:38px;height:38px;border-radius:50%;font-size:25px;font-weight:300}.nav{position:absolute;z-index:3;top:50%;width:44px;height:54px;border-radius:16px;font-size:22px;margin-top:-27px}.previous{left:20px}.next{right:20px}\nbutton:hover:not(:disabled){background:#ffffff20;border-color:#ffffff40}button:active:not(:disabled){transform:scale(.95)}button:disabled{opacity:.4;cursor:default}button:focus-visible,.image:focus-visible{outline:2px solid #b5c8ff;outline-offset:5px}\n.footer{position:absolute;z-index:3;bottom:24px;left:24px;right:24px;display:grid;grid-template-columns:repeat(3,auto);align-items:center;justify-content:space-between;gap:20px}\n.hint{display:contents}.hint>span{white-space:nowrap;color:#a4a6ad;font-size:12px}kbd{font:inherit;color:#eceef6;margin-right:8px}\n.toast{position:absolute;z-index:4;bottom:100px;left:50%;max-width:calc(100vw - 40px);padding:11px 17px;border:1px solid #ffffff24;border-radius:14px;background:#22252e;color:#f5f5f7;font-size:13px;line-height:1.5;text-align:center;transform:translate(-50%,6px);opacity:0;transition:opacity 160ms,transform 160ms;pointer-events:none}.toast.visible{opacity:1;transform:translate(-50%,0)}\n.from-scroll{animation:none!important}.from-scroll .pin-board,.from-scroll .pin-column{animation:none}\n@media(max-width:700px){.topbar{inset:16px 14px auto}.brand{font-size:24px}.stage{padding:74px 14px 122px}.image{max-width:calc(100vw - 28px);max-height:calc(100dvh - 196px);border-radius:10px}.nav{top:auto;bottom:68px;height:38px;width:44px;border-radius:12px}.previous{left:calc(50% - 52px)}.next{right:calc(50% - 52px)}.footer{left:18px;right:18px;bottom:22px;gap:8px}.hint>span{font-size:11px}.hint kbd{margin-right:4px}.toast{bottom:120px}}\n@media(max-width:380px){.hint>span{font-size:10px}.footer{left:14px;right:14px;gap:6px}}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}\n\n.top-actions{display:flex;align-items:center;gap:12px}.capture{display:flex;align-items:center;gap:12px;background:#ffffff10;border:1px solid #ffffff25;border-radius:24px;color:#f3f1eb;padding:9px 15px;font-size:12px}.capture kbd{margin:0;color:#aeb2bb;font-size:11px}.capture[data-saved=\"true\"]{color:#d6e7b5;border-color:#d6e7b540}.continue{color:#c3c5cb;font-size:12px;background:none;border:0;padding:0;display:flex;gap:10px;align-items:center}.capture-pulse{animation:capture-pulse 440ms ease-out}@keyframes capture-pulse{50%{transform:scale(.95);background:#d6e7b526}}\n@media(max-width:700px){.capture{padding:8px 12px;font-size:11px}.top-actions{gap:9px}.continue{font-size:11px}.brand{font-size:25px}}\n.open{width:38px;height:38px;border:1px solid #ffffff26;border-radius:50%;background:#ffffff09;color:#f5f5f7;font:24px Manrope,sans-serif}.open:hover{background:#ffffff18}.image{border-radius:22px}@media(max-width:600px){.image{border-radius:17px}}</style>\n<div class=\"backdrop\" tabindex=\"-1\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Elsewhere gallery\" aria-describedby=\"gallery-hint\">\n<div class=\"pin-board\" aria-hidden=\"true\"></div><div class=\"board-shade\" aria-hidden=\"true\"></div>\n<div class=\"topbar\"><div class=\"brand\">elsewhere</div><div class=\"top-actions\"><button class=\"capture\" type=\"button\" aria-label=\"Capture image\" title=\"Capture \u00b7 M\">Capture <kbd>M</kbd></button><button class=\"open\" type=\"button\" aria-label=\"Open original image\" title=\"Open \u00b7 Enter\">\u21b5</button><button class=\"close\" type=\"button\" aria-label=\"Close gallery\" title=\"Close \u00b7 Esc\">\u00d7</button></div></div>\n<div class=\"stage\"><img class=\"image\" tabindex=\"0\" role=\"button\" aria-label=\"Open preview artwork\" draggable=\"false\" alt=\"\"></div>\n<button class=\"nav previous\" type=\"button\" aria-label=\"Previous image\" title=\"Previous \u00b7 \u2190\">\u2190</button><button class=\"nav next\" type=\"button\" aria-label=\"Next image\" title=\"Next \u00b7 \u2192\">\u2192</button>\n<div class=\"footer\"><div class=\"hint\" id=\"gallery-hint\"><span><kbd>\u2190 \u2192</kbd> browse</span><span><kbd>M</kbd> capture</span><button class=\"continue\" type=\"button\">Keep scrolling <span aria-hidden=\"true\">\u2193</span></button></div></div>\n<div class=\"toast\" role=\"status\"></div></div>";
